// Lesson: MCP Transports: stdio and Stateless Streamable HTTP (phase 13 / lesson 09)
// Go port of code/main.py. Go standard library only.
// Source: phases/13-tools-and-protocols/09-mcp-transports/docs/en.md
// Run: go run code/main.go

package main

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"mime"
	"net"
	"net/http"
	"os"
	"os/signal"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	protocolVersion   = "2026-07-28"
	versionKey        = "io.modelcontextprotocol/protocolVersion"
	capabilitiesKey   = "io.modelcontextprotocol/clientCapabilities"
	clientInfoKey     = "io.modelcontextprotocol/clientInfo"
	serverInfoKey     = "io.modelcontextprotocol/serverInfo"
	subscriptionIDKey = "io.modelcontextprotocol/subscriptionId"
	maxRequestBytes   = 1_048_576
	readTimeout       = 5 * time.Second
)

type obj = map[string]any

var supportedVersions = []string{protocolVersion}

var originAllowlist = map[string]bool{
	"http://localhost":       true,
	"http://127.0.0.1":       true,
	"https://client.example": true,
}

var routingHeaders = []string{"MCP-Protocol-Version", "Mcp-Method", "Mcp-Name"}

func clientInfo() obj { return obj{"name": "lesson-09-client", "version": "2.0.0"} }

func serverInfo() obj { return obj{"name": "lesson-09-http", "version": "2.0.0"} }

func serverCapabilities() obj { return obj{"tools": obj{"listChanged": true}} }

func tools() []obj {
	return []obj{
		{
			"name":        "ping",
			"description": "Return pong for a transport health check.",
			"inputSchema": obj{"type": "object", "properties": obj{}, "required": []any{}},
			"annotations": obj{"readOnlyHint": true, "idempotentHint": true},
		},
	}
}

type rpcFault struct {
	code    int
	message string
	data    any
}

func (f *rpcFault) Error() string { return f.message }

func fault(code int, message string) *rpcFault {
	return &rpcFault{code: code, message: message}
}

func requestMeta(version string) obj {
	return obj{versionKey: version, capabilitiesKey: obj{}, clientInfoKey: clientInfo()}
}

func makeRequest(requestID any, method string, params obj, version string) obj {
	bodyParams := obj{}
	for k, v := range params {
		bodyParams[k] = v
	}
	bodyParams["_meta"] = requestMeta(version)
	return obj{"jsonrpc": "2.0", "id": requestID, "method": method, "params": bodyParams}
}

func rpcError(requestID any, code int, message string, data any) obj {
	e := obj{"code": code, "message": message}
	if data != nil {
		e["data"] = data
	}
	return obj{"jsonrpc": "2.0", "id": requestID, "error": e}
}

func complete(payload obj, ttlMS int, cacheScope string, resultMeta obj) obj {
	metadata := obj{serverInfoKey: serverInfo()}
	for k, v := range resultMeta {
		metadata[k] = v
	}
	result := obj{"resultType": "complete"}
	for k, v := range payload {
		result[k] = v
	}
	result["_meta"] = metadata
	if ttlMS >= 0 {
		result["ttlMs"] = ttlMS
		result["cacheScope"] = cacheScope
	}
	return result
}

func originAllowed(values []string) bool {
	return len(values) == 0 || originAllowlist[values[0]]
}

func printableASCII(s string) bool {
	for _, c := range s {
		if c < 0x20 || c > 0x7E {
			return false
		}
	}
	return true
}

func encodeHeaderValue(value string) string {
	sentinel := strings.HasPrefix(value, "=?base64?") && strings.HasSuffix(value, "?=")
	if printableASCII(value) && value == strings.TrimSpace(value) && !sentinel {
		return value
	}
	return "=?base64?" + base64.StdEncoding.EncodeToString([]byte(value)) + "?="
}

func decodeHeaderValue(value string) (string, error) {
	if strings.HasPrefix(value, "=?base64?") && strings.HasSuffix(value, "?=") {
		raw, err := base64.StdEncoding.DecodeString(value[len("=?base64?") : len(value)-2])
		if err != nil || !utf8.Valid(raw) {
			return "", fault(-32020, "Malformed Base64 MCP header value")
		}
		return string(raw), nil
	}
	if !printableASCII(value) {
		return "", fault(-32020, "Malformed MCP header value")
	}
	return value, nil
}

func bodyName(message obj) (string, bool) {
	params, _ := message["params"].(obj)
	var value any
	switch message["method"] {
	case "resources/read":
		value = params["uri"]
	case "tools/call", "prompts/get":
		value = params["name"]
	default:
		return "", false
	}
	s, ok := value.(string)
	return s, ok
}

func httpHeadersFor(message obj, origin string, extra map[string]string) http.Header {
	meta := message["params"].(obj)["_meta"].(obj)
	h := http.Header{}
	h.Set("Accept", "application/json, text/event-stream")
	h.Set("Content-Type", "application/json")
	h.Set("Origin", origin)
	h.Set("MCP-Protocol-Version", fmt.Sprint(meta[versionKey]))
	h.Set("Mcp-Method", fmt.Sprint(message["method"]))
	if name, ok := bodyName(message); ok {
		h.Set("Mcp-Name", encodeHeaderValue(name))
	}
	for k, v := range extra {
		h.Set(k, v)
	}
	return h
}

func validateRequestStructure(message obj) (string, error) {
	if _, ok := message["method"].(string); !ok || message["jsonrpc"] != "2.0" {
		return "", fault(-32600, "Invalid Request")
	}
	params, ok := message["params"].(obj)
	if !ok {
		return "", fault(-32602, "params must be an object")
	}
	meta, ok := params["_meta"].(obj)
	if !ok {
		return "", fault(-32602, "params._meta is required")
	}
	version, ok := meta[versionKey].(string)
	if !ok {
		return "", fault(-32602, versionKey+" is required")
	}
	if _, ok := meta[capabilitiesKey].(obj); !ok {
		return "", fault(-32602, capabilitiesKey+" is required")
	}
	if info, present := meta[clientInfoKey]; present && info != nil {
		m, ok := info.(obj)
		_, nameOK := m["name"].(string)
		_, versionOK := m["version"].(string)
		if !ok || !nameOK || !versionOK {
			return "", fault(-32602, clientInfoKey+" is malformed")
		}
	}
	return version, nil
}

func validateSupportedVersion(version string) error {
	for _, v := range supportedVersions {
		if v == version {
			return nil
		}
	}
	return &rpcFault{
		code:    -32022,
		message: "Unsupported protocol version",
		data:    obj{"supported": append([]string(nil), supportedVersions...), "requested": version},
	}
}

func validateHTTPHeaders(headers http.Header, message obj, bodyVersion string) error {
	if v := headers.Values("MCP-Protocol-Version"); len(v) == 0 || v[0] != bodyVersion {
		return fault(-32020, "Header mismatch: MCP-Protocol-Version")
	}
	if v := headers.Values("Mcp-Method"); len(v) == 0 || v[0] != message["method"] {
		return fault(-32020, "Header mismatch: Mcp-Method")
	}
	switch message["method"] {
	case "tools/call", "resources/read", "prompts/get":
		expected, ok := bodyName(message)
		v := headers.Values("Mcp-Name")
		if len(v) == 0 || !ok {
			return fault(-32020, "Header mismatch: Mcp-Name")
		}
		decoded, err := decodeHeaderValue(v[0])
		if err != nil {
			return err
		}
		if decoded != expected {
			return fault(-32020, "Header mismatch: Mcp-Name")
		}
	}
	return nil
}

func rejectDuplicateRoutingHeaders(headers http.Header) error {
	for _, name := range routingHeaders {
		if len(headers.Values(name)) > 1 {
			return fault(-32020, "Duplicate routing header: "+name)
		}
	}
	return nil
}

func rejectDuplicateOrigin(headers http.Header) error {
	if len(headers.Values("Origin")) > 1 {
		return fault(-32020, "Duplicate Origin header")
	}
	return nil
}

func dispatch(message obj) obj {
	requestID, ok := message["id"]
	if !ok {
		return nil
	}
	result, err := dispatchResult(message)
	var f *rpcFault
	if errors.As(err, &f) {
		return rpcError(requestID, f.code, f.message, f.data)
	}
	return obj{"jsonrpc": "2.0", "id": requestID, "result": result}
}

func dispatchResult(message obj) (obj, error) {
	version, err := validateRequestStructure(message)
	if err != nil {
		return nil, err
	}
	if err := validateSupportedVersion(version); err != nil {
		return nil, err
	}
	method := message["method"].(string)
	params := message["params"].(obj)
	switch method {
	case "server/discover":
		return complete(obj{
			"supportedVersions": append([]string(nil), supportedVersions...),
			"capabilities":      serverCapabilities(),
			"instructions":      "Call ping for a transport health check.",
		}, 3_600_000, "public", nil), nil
	case "tools/list":
		list := tools()
		sort.Slice(list, func(i, j int) bool { return list[i]["name"].(string) < list[j]["name"].(string) })
		return complete(obj{"tools": list}, 30_000, "public", nil), nil
	case "tools/call":
		args, present := params["arguments"]
		_, argsOK := args.(obj)
		if params["name"] != "ping" || (present && !argsOK) {
			return complete(obj{
				"content": []any{obj{"type": "text", "text": "Unknown or invalid tool"}},
				"isError": true,
			}, -1, "private", nil), nil
		}
		return complete(obj{"content": []any{obj{"type": "text", "text": "pong"}}, "isError": false}, -1, "private", nil), nil
	case "subscriptions/listen":
		if _, ok := params["notifications"].(obj); !ok {
			return nil, fault(-32602, "subscriptions/listen requires notifications")
		}
		return complete(obj{}, -1, "private", nil), nil
	}
	return nil, fault(-32601, "Method not found: "+method)
}

func acceptedFilter(requested obj) obj {
	accepted := obj{}
	for _, key := range []string{"toolsListChanged", "promptsListChanged", "resourcesListChanged"} {
		if requested[key] == true {
			accepted[key] = true
		}
	}
	if resources, ok := requested["resourceSubscriptions"].([]any); ok {
		allStrings := true
		for _, uri := range resources {
			if _, ok := uri.(string); !ok {
				allStrings = false
			}
		}
		if allStrings {
			accepted["resourceSubscriptions"] = append([]any(nil), resources...)
		}
	}
	return accepted
}

func subscriptionMessages(message obj) []obj {
	requestID := message["id"]
	accepted := acceptedFilter(message["params"].(obj)["notifications"].(obj))
	meta := func() obj { return obj{subscriptionIDKey: requestID} }
	messages := []obj{{
		"jsonrpc": "2.0",
		"method":  "notifications/subscriptions/acknowledged",
		"params":  obj{"notifications": accepted, "_meta": meta()},
	}}
	if accepted["toolsListChanged"] == true {
		messages = append(messages, obj{
			"jsonrpc": "2.0",
			"method":  "notifications/tools/list_changed",
			"params":  obj{"_meta": meta()},
		})
	}
	if resources, _ := accepted["resourceSubscriptions"].([]any); len(resources) > 0 {
		messages = append(messages, obj{
			"jsonrpc": "2.0",
			"method":  "notifications/resources/updated",
			"params":  obj{"uri": resources[0], "_meta": meta()},
		})
	}
	return append(messages, obj{"jsonrpc": "2.0", "id": requestID, "result": complete(obj{}, -1, "private", meta())})
}

func compactJSON(v any) []byte {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		panic(err)
	}
	return bytes.TrimRight(buf.Bytes(), "\n")
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

func (w *statusWriter) Flush() {
	if f, ok := w.ResponseWriter.(http.Flusher); ok {
		f.Flush()
	}
}

func writeJSON(w http.ResponseWriter, status int, payload obj) {
	body := compactJSON(payload)
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

func writeFault(w http.ResponseWriter, status int, requestID any, err error) {
	var f *rpcFault
	if !errors.As(err, &f) {
		panic(err)
	}
	writeJSON(w, status, rpcError(requestID, f.code, f.message, f.data))
}

func validPathAndOrigin(w http.ResponseWriter, r *http.Request) bool {
	if r.URL.RequestURI() != "/mcp" {
		writeJSON(w, 404, obj{"error": "Not found"})
		return false
	}
	if err := rejectDuplicateOrigin(r.Header); err != nil {
		writeFault(w, 400, nil, err)
		return false
	}
	if !originAllowed(r.Header.Values("Origin")) {
		writeJSON(w, 403, obj{"error": "Origin not allowed"})
		return false
	}
	return true
}

func readBody(w http.ResponseWriter, r *http.Request) (obj, error) {
	if len(r.TransferEncoding) > 0 {
		return nil, errors.New("Transfer-Encoding is not supported")
	}
	raw := r.Header.Get("Content-Length")
	if raw == "" {
		return nil, errors.New("Content-Length is required")
	}
	for _, c := range raw {
		if c < '0' || c > '9' {
			return nil, errors.New("Content-Length must contain ASCII decimal digits")
		}
	}
	length, err := strconv.Atoi(raw)
	if err != nil || length < 1 || length > maxRequestBytes {
		return nil, fmt.Errorf("Content-Length must be from 1 through %d", maxRequestBytes)
	}
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, int64(length)))
	if err != nil {
		return nil, err
	}
	if len(body) != length {
		return nil, errors.New("request body ended before Content-Length bytes arrived")
	}
	var parsed any
	if err := json.Unmarshal(body, &parsed); err != nil {
		return nil, err
	}
	message, ok := parsed.(obj)
	if !ok {
		return nil, errors.New("message must be an object")
	}
	return message, nil
}

func handlePost(w http.ResponseWriter, r *http.Request) {
	mediaType := strings.ToLower(strings.TrimSpace(strings.SplitN(r.Header.Get("Content-Type"), ";", 2)[0]))
	if mediaType != "application/json" {
		writeJSON(w, 415, obj{"error": "Content-Type must be application/json"})
		return
	}
	accept := r.Header.Get("Accept")
	if !strings.Contains(accept, "application/json") || !strings.Contains(accept, "text/event-stream") {
		writeJSON(w, 406, obj{"error": "Accept must include JSON and SSE"})
		return
	}
	message, err := readBody(w, r)
	if err != nil {
		writeJSON(w, 400, rpcError(nil, -32700, "Parse error", obj{"detail": err.Error()}))
		return
	}
	requestID := message["id"]
	bodyVersion, err := validateRequestStructure(message)
	if err == nil {
		err = rejectDuplicateRoutingHeaders(r.Header)
	}
	if err == nil {
		err = validateHTTPHeaders(r.Header, message, bodyVersion)
	}
	if err == nil {
		err = validateSupportedVersion(bodyVersion)
	}
	if err != nil {
		writeFault(w, 400, requestID, err)
		return
	}
	if _, ok := message["id"]; !ok {
		w.WriteHeader(202)
		return
	}
	if message["method"] == "subscriptions/listen" {
		if _, ok := message["params"].(obj)["notifications"].(obj); !ok {
			writeFault(w, 400, requestID, fault(-32602, "subscriptions/listen requires notifications"))
			return
		}
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("X-Accel-Buffering", "no")
		w.WriteHeader(200)
		for _, payload := range subscriptionMessages(message) {
			_, _ = fmt.Fprintf(w, "data: %s\n\n", compactJSON(payload))
			if f, ok := w.(http.Flusher); ok {
				f.Flush()
			}
		}
		return
	}
	response := dispatch(message)
	status := 200
	if e, ok := response["error"].(obj); ok && e["code"] == -32601 {
		status = 404
	}
	writeJSON(w, status, response)
}

func handler(w http.ResponseWriter, r *http.Request) {
	sw := &statusWriter{ResponseWriter: w, status: 200}
	defer func() {
		fmt.Fprintf(os.Stderr, "[mcp-http] \"%s %s %s\" %d -\n", r.Method, r.URL.RequestURI(), r.Proto, sw.status)
	}()
	if r.Method != http.MethodPost && r.Method != http.MethodGet && r.Method != http.MethodDelete {
		http.Error(sw, fmt.Sprintf("Unsupported method ('%s')", r.Method), 501)
		return
	}
	if !validPathAndOrigin(sw, r) {
		return
	}
	if r.Method != http.MethodPost {
		body := compactJSON(obj{"error": "Method not allowed"})
		sw.Header().Set("Allow", "POST")
		sw.Header().Set("Content-Type", "application/json")
		sw.Header().Set("Content-Length", strconv.Itoa(len(body)))
		sw.WriteHeader(405)
		_, _ = sw.Write(body)
		return
	}
	handlePost(sw, r)
}

func serve(addr string) (*http.Server, string) {
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		panic(err)
	}
	srv := &http.Server{Handler: http.HandlerFunc(handler), ReadTimeout: readTimeout}
	go func() {
		if err := srv.Serve(ln); err != nil && err != http.ErrServerClosed {
			panic(err)
		}
	}()
	return srv, ln.Addr().String()
}

var client = &http.Client{Timeout: 3 * time.Second}

func post(url string, message obj, headers http.Header) (int, http.Header, any) {
	req, err := http.NewRequest(http.MethodPost, url, bytes.NewReader(compactJSON(message)))
	if err != nil {
		panic(err)
	}
	req.Header = headers
	resp, err := client.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		panic(err)
	}
	mediaType, _, _ := mime.ParseMediaType(resp.Header.Get("Content-Type"))
	if mediaType != "application/json" {
		return resp.StatusCode, resp.Header, string(body)
	}
	var payload any
	if err := json.Unmarshal(body, &payload); err != nil {
		panic(err)
	}
	return resp.StatusCode, resp.Header, payload
}

func headerOrNone(h http.Header, name string) string {
	if v := h.Values(name); len(v) > 0 {
		return v[0]
	}
	return "None"
}

func pyBool(b bool) string {
	if b {
		return "True"
	}
	return "False"
}

func dig(v any, path ...any) any {
	for _, p := range path {
		switch k := p.(type) {
		case string:
			v = v.(obj)[k]
		case int:
			v = v.([]any)[k]
		}
	}
	return v
}

func probe() {
	srv, addr := serve("127.0.0.1:0")
	url := "http://" + addr + "/mcp"
	fmt.Println("MCP 2026-07-28 Streamable HTTP probe")

	discover := makeRequest(1, "server/discover", nil, protocolVersion)
	status, _, _ := post(url, discover, httpHeadersFor(discover, "http://evil.example", nil))
	fmt.Printf("  invalid Origin: HTTP %d\n", status)

	status, headers, payload := post(url, discover, httpHeadersFor(discover, "http://localhost", nil))
	fmt.Printf("  discovery: HTTP %d, version=%v, session-header=%s\n",
		status, dig(payload, "result", "supportedVersions", 0), headerOrNone(headers, "Mcp-Session-Id"))

	listing := makeRequest(2, "tools/list", nil, protocolVersion)
	removed := map[string]string{"Mcp-Session-Id": "ignored", "Last-Event-ID": "ignored"}
	status, headers, payload = post(url, listing, httpHeadersFor(listing, "http://localhost", removed))
	fmt.Printf("  removed headers ignored: HTTP %d, tool=%v, echo=%s\n",
		status, dig(payload, "result", "tools", 0, "name"), headerOrNone(headers, "Mcp-Session-Id"))

	mismatched := httpHeadersFor(listing, "http://localhost", nil)
	mismatched.Set("Mcp-Method", "tools/call")
	status, _, payload = post(url, listing, mismatched)
	fmt.Printf("  header mismatch: HTTP %d, code=%v\n", status, dig(payload, "error", "code"))

	future := makeRequest(3, "tools/list", nil, "2027-01-01")
	status, _, payload = post(url, future, httpHeadersFor(future, "http://localhost", nil))
	fmt.Printf("  unsupported version: HTTP %d, code=%v\n", status, dig(payload, "error", "code"))

	notification := makeRequest(4, "tools/list", nil, protocolVersion)
	delete(notification, "id")
	status, _, payload = post(url, notification, httpHeadersFor(notification, "http://localhost", nil))
	fmt.Printf("  accepted notification: HTTP %d, empty-body=%s\n", status, pyBool(payload == ""))

	for _, method := range []string{"GET", "DELETE"} {
		req, err := http.NewRequest(method, url, nil)
		if err != nil {
			panic(err)
		}
		req.Header.Set("Origin", "http://localhost")
		resp, err := client.Do(req)
		if err != nil {
			panic(err)
		}
		_ = resp.Body.Close()
		if resp.StatusCode >= 400 {
			fmt.Printf("  %s: HTTP %d\n", method, resp.StatusCode)
		}
	}

	listen := makeRequest("listen-1", "subscriptions/listen", obj{"notifications": obj{"toolsListChanged": true}}, protocolVersion)
	status, _, stream := post(url, listen, httpHeadersFor(listen, "http://localhost", nil))
	text, _ := stream.(string)
	fmt.Printf("  subscriptions/listen: HTTP %d, SSE=%s, tagged=%s\n", status,
		pyBool(strings.Contains(text, "notifications/subscriptions/acknowledged")),
		pyBool(strings.Contains(text, subscriptionIDKey)))

	if err := srv.Close(); err != nil {
		panic(err)
	}
}

func main() {
	serveMode := false
	for _, a := range os.Args[1:] {
		if a == "--serve" {
			serveMode = true
		}
	}
	if !serveMode {
		probe()
		return
	}
	srv, _ := serve("127.0.0.1:8017")
	fmt.Println("MCP 2026-07-28 endpoint: http://127.0.0.1:8017/mcp")
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt)
	<-stop
	if err := srv.Close(); err != nil {
		panic(err)
	}
}

"""Phase 13 Lesson 09: stateless MCP Streamable HTTP.
Lesson: phases/13-tools-and-protocols/09-mcp-transports/docs/en.md
Specification: https://modelcontextprotocol.io/specification/2026-07-28/
Implements POST-only transport, header validation, JSON, and finite SSE.
Run: python3 main.py
"""

from __future__ import annotations

import base64
import json
import sys
import threading
import time
import urllib.error
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Mapping


PROTOCOL_VERSION = "2026-07-28"
SUPPORTED_VERSIONS = [PROTOCOL_VERSION]
VERSION_KEY = "io.modelcontextprotocol/protocolVersion"
CAPABILITIES_KEY = "io.modelcontextprotocol/clientCapabilities"
CLIENT_INFO_KEY = "io.modelcontextprotocol/clientInfo"
SERVER_INFO_KEY = "io.modelcontextprotocol/serverInfo"
SUBSCRIPTION_ID_KEY = "io.modelcontextprotocol/subscriptionId"

CLIENT_INFO = {"name": "lesson-09-client", "version": "2.0.0"}
SERVER_INFO = {"name": "lesson-09-http", "version": "2.0.0"}
SERVER_CAPABILITIES = {"tools": {"listChanged": True}}
ORIGIN_ALLOWLIST = {
    "http://localhost",
    "http://127.0.0.1",
    "https://client.example",
}
MAX_REQUEST_BYTES = 1_048_576
READ_TIMEOUT_SECONDS = 5.0
ROUTING_HEADERS = ("MCP-Protocol-Version", "Mcp-Method", "Mcp-Name")

TOOLS = [
    {
        "name": "ping",
        "description": "Return pong for a transport health check.",
        "inputSchema": {"type": "object", "properties": {}, "required": []},
        "annotations": {"readOnlyHint": True, "idempotentHint": True},
    }
]


class RpcFault(Exception):
    def __init__(self, code: int, message: str, data: Any | None = None) -> None:
        super().__init__(message)
        self.code = code
        self.data = data


def request_meta(version: str = PROTOCOL_VERSION) -> dict[str, Any]:
    return {
        VERSION_KEY: version,
        CAPABILITIES_KEY: {},
        CLIENT_INFO_KEY: CLIENT_INFO.copy(),
    }


def make_request(
    request_id: int | str,
    method: str,
    params: dict[str, Any] | None = None,
    *,
    version: str = PROTOCOL_VERSION,
) -> dict[str, Any]:
    body_params = dict(params or {})
    body_params["_meta"] = request_meta(version)
    return {"jsonrpc": "2.0", "id": request_id, "method": method, "params": body_params}


def rpc_error(
    request_id: int | str | None,
    code: int,
    message: str,
    data: Any | None = None,
) -> dict[str, Any]:
    error: dict[str, Any] = {"code": code, "message": message}
    if data is not None:
        error["data"] = data
    return {"jsonrpc": "2.0", "id": request_id, "error": error}


def complete(
    payload: dict[str, Any],
    *,
    ttl_ms: int | None = None,
    cache_scope: str = "private",
    result_meta: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    metadata = {SERVER_INFO_KEY: SERVER_INFO.copy()}
    if result_meta:
        metadata.update(result_meta)
    result = {
        "resultType": "complete",
        **payload,
        "_meta": metadata,
    }
    if ttl_ms is not None:
        result["ttlMs"] = ttl_ms
        result["cacheScope"] = cache_scope
    return result


def origin_allowed(origin: str | None) -> bool:
    return origin is None or origin in ORIGIN_ALLOWLIST


def encode_header_value(value: str) -> str:
    safe = all(0x20 <= ord(character) <= 0x7E for character in value)
    sentinel = value.startswith("=?base64?") and value.endswith("?=")
    if safe and value == value.strip() and not sentinel:
        return value
    encoded = base64.b64encode(value.encode("utf-8")).decode("ascii")
    return f"=?base64?{encoded}?="


def decode_header_value(value: str) -> str:
    if value.startswith("=?base64?") and value.endswith("?="):
        encoded = value[len("=?base64?") : -2]
        try:
            return base64.b64decode(encoded, validate=True).decode("utf-8")
        except (ValueError, UnicodeDecodeError) as exc:
            raise RpcFault(-32020, "Malformed Base64 MCP header value") from exc
    if any(ord(character) < 0x20 or ord(character) > 0x7E for character in value):
        raise RpcFault(-32020, "Malformed MCP header value")
    return value


def body_name(message: dict[str, Any]) -> str | None:
    params = message.get("params", {})
    if message.get("method") == "resources/read":
        value = params.get("uri")
    elif message.get("method") in {"tools/call", "prompts/get"}:
        value = params.get("name")
    else:
        return None
    return value if isinstance(value, str) else None


def http_headers_for(
    message: dict[str, Any],
    *,
    origin: str = "http://localhost",
    extra: Mapping[str, str] | None = None,
) -> dict[str, str]:
    meta = message["params"]["_meta"]
    headers = {
        "Accept": "application/json, text/event-stream",
        "Content-Type": "application/json",
        "Origin": origin,
        "MCP-Protocol-Version": str(meta[VERSION_KEY]),
        "Mcp-Method": str(message["method"]),
    }
    name = body_name(message)
    if name is not None:
        headers["Mcp-Name"] = encode_header_value(name)
    if extra:
        headers.update(extra)
    return headers


def validate_request_structure(message: dict[str, Any]) -> str:
    if message.get("jsonrpc") != "2.0" or not isinstance(message.get("method"), str):
        raise RpcFault(-32600, "Invalid Request")
    params = message.get("params")
    if not isinstance(params, dict):
        raise RpcFault(-32602, "params must be an object")
    meta = params.get("_meta")
    if not isinstance(meta, dict):
        raise RpcFault(-32602, "params._meta is required")
    version = meta.get(VERSION_KEY)
    if not isinstance(version, str):
        raise RpcFault(-32602, f"{VERSION_KEY} is required")
    if not isinstance(meta.get(CAPABILITIES_KEY), dict):
        raise RpcFault(-32602, f"{CAPABILITIES_KEY} is required")
    client_info = meta.get(CLIENT_INFO_KEY)
    if client_info is not None and (
        not isinstance(client_info, dict)
        or not isinstance(client_info.get("name"), str)
        or not isinstance(client_info.get("version"), str)
    ):
        raise RpcFault(-32602, f"{CLIENT_INFO_KEY} is malformed")
    return version


def validate_supported_version(version: str) -> None:
    if version not in SUPPORTED_VERSIONS:
        raise RpcFault(
            -32022,
            "Unsupported protocol version",
            {"supported": SUPPORTED_VERSIONS.copy(), "requested": version},
        )


def validate_http_headers(
    headers: Mapping[str, str],
    message: dict[str, Any],
    body_version: str,
) -> None:
    header_version = headers.get("MCP-Protocol-Version")
    if header_version is None or header_version != body_version:
        raise RpcFault(-32020, "Header mismatch: MCP-Protocol-Version")
    header_method = headers.get("Mcp-Method")
    if header_method is None or header_method != message["method"]:
        raise RpcFault(-32020, "Header mismatch: Mcp-Method")
    expected_name = body_name(message)
    if message["method"] in {"tools/call", "resources/read", "prompts/get"}:
        header_name = headers.get("Mcp-Name")
        if header_name is None or expected_name is None:
            raise RpcFault(-32020, "Header mismatch: Mcp-Name")
        if decode_header_value(header_name) != expected_name:
            raise RpcFault(-32020, "Header mismatch: Mcp-Name")


def reject_duplicate_routing_headers(headers: Any) -> None:
    get_all = getattr(headers, "get_all", None)
    if not callable(get_all):
        return
    for name in ROUTING_HEADERS:
        if len(get_all(name, [])) > 1:
            raise RpcFault(-32020, f"Duplicate routing header: {name}")


def reject_duplicate_origin(headers: Any) -> None:
    get_all = getattr(headers, "get_all", None)
    if callable(get_all) and len(get_all("Origin", [])) > 1:
        raise RpcFault(-32020, "Duplicate Origin header")


def reject_ambiguous_body_framing(headers: Any) -> None:
    get_all = getattr(headers, "get_all", None)
    if not callable(get_all):
        return
    if len(get_all("Content-Length", [])) > 1:
        raise ValueError("duplicate Content-Length headers are not allowed")
    if get_all("Transfer-Encoding", []):
        raise ValueError("Transfer-Encoding is not supported")


def dispatch(message: dict[str, Any]) -> dict[str, Any] | None:
    if "id" not in message:
        return None
    request_id = message["id"]
    try:
        version = validate_request_structure(message)
        validate_supported_version(version)
        method = message["method"]
        params = message["params"]
        if method == "server/discover":
            result = complete(
                {
                    "supportedVersions": SUPPORTED_VERSIONS.copy(),
                    "capabilities": SERVER_CAPABILITIES.copy(),
                    "instructions": "Call ping for a transport health check.",
                },
                ttl_ms=3_600_000,
                cache_scope="public",
            )
        elif method == "tools/list":
            result = complete(
                {"tools": sorted(TOOLS, key=lambda tool: tool["name"])},
                ttl_ms=30_000,
                cache_scope="public",
            )
        elif method == "tools/call":
            if params.get("name") != "ping" or not isinstance(params.get("arguments", {}), dict):
                result = complete(
                    {
                        "content": [{"type": "text", "text": "Unknown or invalid tool"}],
                        "isError": True,
                    }
                )
            else:
                result = complete(
                    {"content": [{"type": "text", "text": "pong"}], "isError": False}
                )
        elif method == "subscriptions/listen":
            notifications = params.get("notifications")
            if not isinstance(notifications, dict):
                raise RpcFault(-32602, "subscriptions/listen requires notifications")
            result = complete({})
        else:
            raise RpcFault(-32601, f"Method not found: {method}")
        return {"jsonrpc": "2.0", "id": request_id, "result": result}
    except RpcFault as exc:
        return rpc_error(request_id, exc.code, str(exc), exc.data)


def accepted_filter(requested: dict[str, Any]) -> dict[str, Any]:
    accepted: dict[str, Any] = {}
    for key in ("toolsListChanged", "promptsListChanged", "resourcesListChanged"):
        if requested.get(key) is True:
            accepted[key] = True
    resources = requested.get("resourceSubscriptions")
    if isinstance(resources, list) and all(isinstance(uri, str) for uri in resources):
        accepted["resourceSubscriptions"] = resources.copy()
    return accepted


def subscription_messages(message: dict[str, Any]) -> list[dict[str, Any]]:
    request_id = message["id"]
    requested = message["params"]["notifications"]
    accepted = accepted_filter(requested)
    subscription_meta = {SUBSCRIPTION_ID_KEY: request_id}
    messages: list[dict[str, Any]] = [
        {
            "jsonrpc": "2.0",
            "method": "notifications/subscriptions/acknowledged",
            "params": {"notifications": accepted, "_meta": subscription_meta.copy()},
        }
    ]
    if accepted.get("toolsListChanged"):
        messages.append(
            {
                "jsonrpc": "2.0",
                "method": "notifications/tools/list_changed",
                "params": {"_meta": subscription_meta.copy()},
            }
        )
    resources = accepted.get("resourceSubscriptions", [])
    if resources:
        messages.append(
            {
                "jsonrpc": "2.0",
                "method": "notifications/resources/updated",
                "params": {"uri": resources[0], "_meta": subscription_meta.copy()},
            }
        )
    messages.append(
        {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": complete({}, result_meta=subscription_meta),
        }
    )
    return messages


class Handler(BaseHTTPRequestHandler):
    def log_message(self, format_string: str, *args: Any) -> None:
        sys.stderr.write("[mcp-http] " + (format_string % args) + "\n")

    def _write_json(self, status: int, payload: dict[str, Any]) -> None:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _write_fault(self, status: int, request_id: Any, fault: RpcFault) -> None:
        self._write_json(status, rpc_error(request_id, fault.code, str(fault), fault.data))

    def _valid_path_and_origin(self) -> bool:
        if self.path != "/mcp":
            self._write_json(404, {"error": "Not found"})
            return False
        try:
            reject_duplicate_origin(self.headers)
        except RpcFault as fault:
            self._write_fault(400, None, fault)
            return False
        origin = self.headers.get("Origin")
        if not origin_allowed(origin):
            self._write_json(403, {"error": "Origin not allowed"})
            return False
        return True

    def _method_not_allowed(self) -> None:
        body = json.dumps({"error": "Method not allowed"}).encode("utf-8")
        self.send_response(405)
        self.send_header("Allow", "POST")
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _write_subscription_stream(self, message: dict[str, Any]) -> None:
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Accel-Buffering", "no")
        self.end_headers()
        for payload in subscription_messages(message):
            self.wfile.write(
                f"data: {json.dumps(payload, separators=(',', ':'))}\n\n".encode("utf-8")
            )
            self.wfile.flush()

    def do_POST(self) -> None:
        if not self._valid_path_and_origin():
            return
        content_type = self.headers.get("Content-Type", "").split(";", 1)[0].strip().lower()
        if content_type != "application/json":
            self._write_json(415, {"error": "Content-Type must be application/json"})
            return
        accept = self.headers.get("Accept", "")
        if "application/json" not in accept or "text/event-stream" not in accept:
            self._write_json(406, {"error": "Accept must include JSON and SSE"})
            return
        try:
            reject_ambiguous_body_framing(self.headers)
            raw_length = self.headers.get("Content-Length")
            if raw_length is None:
                raise ValueError("Content-Length is required")
            if not raw_length.isascii() or not raw_length.isdigit():
                raise ValueError("Content-Length must contain ASCII decimal digits")
            length = int(raw_length)
            if not 1 <= length <= MAX_REQUEST_BYTES:
                raise ValueError(
                    f"Content-Length must be from 1 through {MAX_REQUEST_BYTES}"
                )
            self.connection.settimeout(READ_TIMEOUT_SECONDS)
            body = self.rfile.read(length)
            if len(body) != length:
                raise ValueError("request body ended before Content-Length bytes arrived")
            message = json.loads(body)
            if not isinstance(message, dict):
                raise ValueError("message must be an object")
        except (ValueError, json.JSONDecodeError, TimeoutError) as exc:
            self._write_json(400, rpc_error(None, -32700, "Parse error", {"detail": str(exc)}))
            return

        request_id = message.get("id")
        try:
            body_version = validate_request_structure(message)
            reject_duplicate_routing_headers(self.headers)
            validate_http_headers(self.headers, message, body_version)
            validate_supported_version(body_version)
        except RpcFault as fault:
            self._write_fault(400, request_id, fault)
            return

        if "id" not in message:
            self.send_response(202)
            self.end_headers()
            return

        if message["method"] == "subscriptions/listen":
            notifications = message["params"].get("notifications")
            if not isinstance(notifications, dict):
                self._write_fault(
                    400,
                    request_id,
                    RpcFault(-32602, "subscriptions/listen requires notifications"),
                )
                return
            self._write_subscription_stream(message)
            return

        response = dispatch(message)
        status = 404 if response and response.get("error", {}).get("code") == -32601 else 200
        if response is not None:
            self._write_json(status, response)

    def do_GET(self) -> None:
        if self._valid_path_and_origin():
            self._method_not_allowed()

    def do_DELETE(self) -> None:
        if self._valid_path_and_origin():
            self._method_not_allowed()


def serve(host: str = "127.0.0.1", port: int = 0) -> ThreadingHTTPServer:
    server = ThreadingHTTPServer((host, port), Handler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    return server


def post(url: str, message: dict[str, Any], headers: Mapping[str, str]) -> tuple[int, Any, Any]:
    request = urllib.request.Request(
        url,
        data=json.dumps(message).encode("utf-8"),
        headers=dict(headers),
        method="POST",
    )
    try:
        response = urllib.request.urlopen(request, timeout=3)
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8")
        status = exc.code
        response_headers = exc.headers
        exc.close()
        return status, response_headers, json.loads(body) if body else None
    with response:
        body = response.read().decode("utf-8")
        if response.headers.get_content_type() == "application/json":
            payload: Any = json.loads(body)
        else:
            payload = body
        return response.status, response.headers, payload


def probe() -> None:
    server = serve()
    url = f"http://127.0.0.1:{server.server_port}/mcp"
    print("MCP 2026-07-28 Streamable HTTP probe")

    discover = make_request(1, "server/discover")
    status, _, _ = post(url, discover, http_headers_for(discover, origin="http://evil.example"))
    print(f"  invalid Origin: HTTP {status}")

    status, headers, payload = post(url, discover, http_headers_for(discover))
    print(
        f"  discovery: HTTP {status}, version={payload['result']['supportedVersions'][0]}, "
        f"session-header={headers.get('Mcp-Session-Id')}"
    )

    listing = make_request(2, "tools/list")
    removed = {"Mcp-Session-Id": "ignored", "Last-Event-ID": "ignored"}
    status, headers, payload = post(url, listing, http_headers_for(listing, extra=removed))
    print(
        f"  removed headers ignored: HTTP {status}, tool={payload['result']['tools'][0]['name']}, "
        f"echo={headers.get('Mcp-Session-Id')}"
    )

    mismatched = http_headers_for(listing)
    mismatched["Mcp-Method"] = "tools/call"
    status, _, payload = post(url, listing, mismatched)
    print(f"  header mismatch: HTTP {status}, code={payload['error']['code']}")

    future = make_request(3, "tools/list", version="2027-01-01")
    status, _, payload = post(url, future, http_headers_for(future))
    print(f"  unsupported version: HTTP {status}, code={payload['error']['code']}")

    notification = make_request(4, "tools/list")
    del notification["id"]
    status, _, payload = post(url, notification, http_headers_for(notification))
    print(f"  accepted notification: HTTP {status}, empty-body={payload == ''}")

    for method in ("GET", "DELETE"):
        request = urllib.request.Request(
            url,
            headers={"Origin": "http://localhost"},
            method=method,
        )
        try:
            urllib.request.urlopen(request, timeout=3)
        except urllib.error.HTTPError as exc:
            status = exc.code
            exc.close()
            print(f"  {method}: HTTP {status}")

    listen = make_request(
        "listen-1",
        "subscriptions/listen",
        {"notifications": {"toolsListChanged": True}},
    )
    status, _, stream = post(url, listen, http_headers_for(listen))
    print(
        f"  subscriptions/listen: HTTP {status}, "
        f"SSE={('notifications/subscriptions/acknowledged' in stream)}, "
        f"tagged={SUBSCRIPTION_ID_KEY in stream}"
    )

    server.shutdown()
    server.server_close()


def main() -> None:
    if "--serve" not in sys.argv:
        probe()
        return
    server = serve("127.0.0.1", 8017)
    print("MCP 2026-07-28 endpoint: http://127.0.0.1:8017/mcp")
    try:
        while True:
            time.sleep(60)
    except KeyboardInterrupt:
        server.shutdown()
        server.server_close()


if __name__ == "__main__":
    main()

